enum AccessLevel { VIEW, COMMENT, EDIT }
enum SessionState { ACTIVE, CLOSED }

// ── Strategy Pattern: one interface, four implementations ──
interface AccessPolicy {
    boolean canView();
    boolean canComment();
    boolean canEdit();
    boolean canDelete();
    boolean canShare();
}

class ViewPolicy implements AccessPolicy {
    public boolean canView()    { return true;  }
    public boolean canComment() { return false; }
    public boolean canEdit()    { return false; }
    public boolean canDelete()  { return false; }
    public boolean canShare()   { return false; }
}

class CommentPolicy implements AccessPolicy {
    public boolean canView()    { return true;  }
    public boolean canComment() { return true;  }
    public boolean canEdit()    { return false; }
    public boolean canDelete()  { return false; }
    public boolean canShare()   { return false; }
}

class EditPolicy implements AccessPolicy {
    public boolean canView()    { return true;  }
    public boolean canComment() { return true;  }
    public boolean canEdit()    { return true;  }
    public boolean canDelete()  { return false; }
    public boolean canShare()   { return false; }
}

class OwnerPolicy implements AccessPolicy {
    public boolean canView()    { return true;  }
    public boolean canComment() { return true;  }
    public boolean canEdit()    { return true;  }
    public boolean canDelete()  { return true;  }
    public boolean canShare()   { return true;  }
}

// ── Factory: enum → policy ──
class AccessPolicyFactory {
    public static AccessPolicy getPolicy(AccessLevel level) {
        return switch (level) {
            case VIEW    -> new ViewPolicy();
            case COMMENT -> new CommentPolicy();
            case EDIT    -> new EditPolicy();
        };
    }
}

import java.time.LocalDateTime;
import java.util.*;

class User {
    final String id, name, email;
    final LocalDateTime createdAt;
    public User(String id, String name, String email) {
        this.id = id; this.name = name; this.email = email;
        this.createdAt = LocalDateTime.now();
    }
}

class Document {
    final String id;
    String name;
    String content;
    final User owner;
    int currentVersionNum = 0;
    final List<Version> versionHistory = new ArrayList<>();
    final LocalDateTime createdAt;
    LocalDateTime updatedAt;

    public Document(String id, String name, String content, User owner) {
        this.id = id; this.name = name; this.content = content;
        this.owner = owner;
        this.createdAt = LocalDateTime.now();
        this.updatedAt = this.createdAt;
    }

    public void applyEdit(String newContent) {
        this.content = newContent;
        this.updatedAt = LocalDateTime.now();
    }

    public int incrementVersion() {
        return ++currentVersionNum;
    }

    public void revertTo(Version v) {
        this.content = v.content;
        this.updatedAt = LocalDateTime.now();
    }

    public boolean isOwnedBy(User u) {
        return owner.id.equals(u.id);
    }
}

// Immutable — no setters, all final
class Version {
    final String id;
    final int versionNumber;
    final String documentId;
    final String content;
    final User savedBy;
    final String message;
    final LocalDateTime createdAt;

    public Version(String documentId, int versionNumber,
                   String content, User savedBy, String message) {
        this.id = UUID.randomUUID().toString();
        this.versionNumber = versionNumber;
        this.documentId = documentId;
        this.content = content;
        this.savedBy = savedBy;
        this.message = message;
        this.createdAt = LocalDateTime.now();
    }
}

// Ephemeral — overwritten on every edit, discarded on session close
class Snapshot {
    final String id;
    final String sessionId;
    final String documentId;
    String content;
    LocalDateTime updatedAt;

    public Snapshot(String sessionId, String documentId, String content) {
        this.id = UUID.randomUUID().toString();
        this.sessionId = sessionId;
        this.documentId = documentId;
        this.content = content;
        this.updatedAt = LocalDateTime.now();
    }

    public void updateContent(String c) {
        this.content = c;
        this.updatedAt = LocalDateTime.now();
    }
}

class EditSession {
    final String id;
    final String documentId;
    final User user;
    final AccessLevel accessLevel;
    SessionState state;
    Snapshot currentSnapshot;
    final LocalDateTime openedAt;
    LocalDateTime closedAt;

    public EditSession(String documentId, User user, AccessLevel level) {
        this.id = UUID.randomUUID().toString();
        this.documentId = documentId;
        this.user = user;
        this.accessLevel = level;
        this.state = SessionState.ACTIVE;
        this.openedAt = LocalDateTime.now();
    }

    public boolean isActive() { return state == SessionState.ACTIVE; }

    public void close() {
        this.state = SessionState.CLOSED;
        this.closedAt = LocalDateTime.now();
        this.currentSnapshot = null; // discard
    }

    public boolean canEdit() {
        return AccessPolicyFactory.getPolicy(accessLevel).canEdit();
    }

    public boolean canComment() {
        return AccessPolicyFactory.getPolicy(accessLevel).canComment();
    }
}

class Share {
    final String id;
    final String documentId;
    final User sharedBy;
    final User sharedWith;
    AccessLevel accessLevel;
    final LocalDateTime sharedOn;

    public Share(String documentId, User sharedBy, User sharedWith, AccessLevel level) {
        this.id = UUID.randomUUID().toString();
        this.documentId = documentId;
        this.sharedBy = sharedBy;
        this.sharedWith = sharedWith;
        this.accessLevel = level;
        this.sharedOn = LocalDateTime.now();
    }
}

class Comment {
    final String id;
    final String documentId;
    final User author;
    final String content;
    final int positionStart;
    final int positionEnd;
    boolean resolved = false;
    final LocalDateTime createdAt;

    public Comment(String documentId, User author, String content, int start, int end) {
        this.id = UUID.randomUUID().toString();
        this.documentId = documentId;
        this.author = author;
        this.content = content;
        this.positionStart = start;
        this.positionEnd = end;
        this.createdAt = LocalDateTime.now();
    }

    public void resolve() { this.resolved = true; }
}

class ShareService {
    // documentId → list of shares
    private final Map<String, List<Share>> documentSharesMap = new ConcurrentHashMap<>();
    private final Map<String, Document> documentStore; // injected

    public ShareService(Map<String, Document> documentStore) {
        this.documentStore = documentStore;
    }

    // ── The most important method in the entire system ──
    public AccessPolicy resolveAccess(User user, Document document) {
        if (document.isOwnedBy(user)) return new OwnerPolicy();

        List<Share> shares = documentSharesMap.getOrDefault(document.id, List.of());
        return shares.stream()
            .filter(s -> s.sharedWith.id.equals(user.id))
            .findFirst()
            .map(s -> AccessPolicyFactory.getPolicy(s.accessLevel))
            .orElseThrow(() -> new UserNotHaveAccessException(
                user.id + " has no access to document " + document.id));
    }

    public Share shareDocument(User owner, String documentId,
                                User target, AccessLevel level) {
        Document doc = documentStore.get(documentId);
        if (doc == null) throw new DocumentNotFoundException(documentId);
        if (!doc.isOwnedBy(owner))
            throw new UserNotHaveAccessException("Only owner can share");
        if (owner.id.equals(target.id))
            throw new IllegalArgumentException("Cannot share with yourself");

        List<Share> shares = documentSharesMap
            .computeIfAbsent(documentId, k -> new CopyOnWriteArrayList<>());

        boolean exists = shares.stream()
            .anyMatch(s -> s.sharedWith.id.equals(target.id));
        if (exists) throw new UserAlreadyHasAccessException(
            target.id + " already has access");

        Share share = new Share(documentId, owner, target, level);
        shares.add(share);
        return share;
    }

    public void revokeShare(User owner, String documentId, User target) {
        Document doc = documentStore.get(documentId);
        if (doc == null) throw new DocumentNotFoundException(documentId);
        if (!doc.isOwnedBy(owner))
            throw new UserNotHaveAccessException("Only owner can revoke");

        List<Share> shares = documentSharesMap.getOrDefault(documentId, List.of());
        shares.removeIf(s -> s.sharedWith.id.equals(target.id));
    }

    public void updateAccess(User owner, String documentId,
                              User target, AccessLevel newLevel) {
        Document doc = documentStore.get(documentId);
        if (!doc.isOwnedBy(owner))
            throw new UserNotHaveAccessException("Only owner");

        List<Share> shares = documentSharesMap.getOrDefault(documentId, List.of());
        Share share = shares.stream()
            .filter(s -> s.sharedWith.id.equals(target.id))
            .findFirst()
            .orElseThrow(() -> new UserNotHaveAccessException("No existing share"));
        share.accessLevel = newLevel;
    }

    public List<Share> getSharesForDocument(String documentId) {
        return documentSharesMap.getOrDefault(documentId, List.of());
    }
}

class SessionService {
    private final Map<String, EditSession> sessionStore = new ConcurrentHashMap<>();
    private final Map<String, Document> documentStore; // injected
    private final ShareService shareService;

    public SessionService(Map<String, Document> docs, ShareService shareService) {
        this.documentStore = docs;
        this.shareService = shareService;
    }

    public EditSession openSession(User user, String documentId) {
        Document doc = documentStore.get(documentId);
        if (doc == null) throw new DocumentNotFoundException(documentId);

        // Resolve access — throws if no access
        AccessPolicy policy = shareService.resolveAccess(user, doc);
        if (!policy.canView())
            throw new UserNotHaveAccessException("No view access");

        // Determine the user's access level for the session
        AccessLevel level;
        if (doc.isOwnedBy(user)) level = AccessLevel.EDIT; // owner gets EDIT
        else {
            Share share = shareService.getSharesForDocument(documentId).stream()
                .filter(s -> s.sharedWith.id.equals(user.id))
                .findFirst().orElseThrow();
            level = share.accessLevel;
        }

        EditSession session = new EditSession(documentId, user, level);
        // Create initial snapshot from current document content
        Snapshot snapshot = new Snapshot(session.id, documentId, doc.content);
        session.currentSnapshot = snapshot;

        sessionStore.put(session.id, session);
        return session;
    }

    public Snapshot editDocument(User user, String sessionId, String newContent) {
        EditSession session = getSession(sessionId);

        if (!session.isActive())
            throw new SessionNotActiveException(sessionId);
        if (!session.user.id.equals(user.id))
            throw new UserNotHaveAccessException("Not your session");
        if (!session.canEdit())
            throw new DocumentNotEditableException(
                "Access level " + session.accessLevel + " cannot edit");

        // Overwrite the ephemeral snapshot — NOT the document
        session.currentSnapshot.updateContent(newContent);
        return session.currentSnapshot;
    }

    public void closeSession(User user, String sessionId) {
        EditSession session = getSession(sessionId);
        if (!session.user.id.equals(user.id))
            throw new UserNotHaveAccessException("Not your session");
        session.close(); // state=CLOSED, snapshot=null
    }

    public EditSession getSession(String sessionId) {
        EditSession session = sessionStore.get(sessionId);
        if (session == null)
            throw new SessionNotFoundException(sessionId);
        return session;
    }

    // Used by DocumentService on delete — close all sessions for a document
    public void closeAllSessionsForDocument(String documentId) {
        sessionStore.values().stream()
            .filter(s -> s.documentId.equals(documentId) && s.isActive())
            .forEach(EditSession::close);
    }
}

class DocumentService {
    private final Map<String, Document> documentStore = new ConcurrentHashMap<>();
    private final ShareService shareService;
    private final SessionService sessionService;

    public DocumentService(ShareService shareService, SessionService sessionService) {
        this.shareService = shareService;
        this.sessionService = sessionService;
    }

    public Document createDocument(User owner, String name, String content) {
        Document doc = new Document(UUID.randomUUID().toString(), name, content, owner);
        // Create initial version (v1)
        int vNum = doc.incrementVersion();
        Version v1 = new Version(doc.id, vNum, content, owner, "Initial version");
        doc.versionHistory.add(v1);
        documentStore.put(doc.id, doc);
        return doc;
    }

    public Document getDocument(User requester, String documentId) {
        Document doc = documentStore.get(documentId);
        if (doc == null) throw new DocumentNotFoundException(documentId);
        AccessPolicy policy = shareService.resolveAccess(requester, doc);
        if (!policy.canView())
            throw new UserNotHaveAccessException("No view access");
        return doc;
    }

    // ── Save: snapshot content → new Version → update document ──
    public Version saveDocument(User requester, String sessionId, String message) {
        EditSession session = sessionService.getSession(sessionId);

        if (!session.isActive())
            throw new SessionNotActiveException(sessionId);
        if (!session.user.id.equals(requester.id))
            throw new UserNotHaveAccessException("Not your session");
        if (!session.canEdit())
            throw new DocumentNotEditableException("Cannot save with " + session.accessLevel);

        Document doc = documentStore.get(session.documentId);

        // ── Optimistic locking: check version hasn't changed ──
        // (In a real system, session would store the versionNum at open time)
        // For now, we just proceed — mention the pattern

        String snapshotContent = session.currentSnapshot.content;
        int newVersionNum = doc.incrementVersion();

        Version version = new Version(
            doc.id, newVersionNum, snapshotContent, requester,
            message != null ? message : "Version " + newVersionNum);
        doc.versionHistory.add(version);
        doc.applyEdit(snapshotContent); // commit to document

        return version;
    }

    public void deleteDocument(User requester, String documentId) {
        Document doc = documentStore.get(documentId);
        if (doc == null) throw new DocumentNotFoundException(documentId);
        if (!doc.isOwnedBy(requester))
            throw new UserNotHaveAccessException("Only owner can delete");

        // Cascade: close all sessions, remove shares, remove doc
        sessionService.closeAllSessionsForDocument(documentId);
        // shareService would also remove all shares (omitted for brevity)
        documentStore.remove(documentId);
    }

    // ── Revert: find old version → create NEW version with old content ──
    public Document revertToVersion(User requester, String documentId, int versionNumber) {
        Document doc = getDocument(requester, documentId);
        AccessPolicy policy = shareService.resolveAccess(requester, doc);
        if (!policy.canEdit())
            throw new DocumentNotEditableException("Cannot revert without EDIT access");

        Version targetVersion = doc.versionHistory.stream()
            .filter(v -> v.versionNumber == versionNumber)
            .findFirst()
            .orElseThrow(() -> new VersionNotFoundException(
                "Version " + versionNumber + " not found"));

        // Append-only: revert creates a NEW version with old content
        doc.revertTo(targetVersion);
        int newNum = doc.incrementVersion();
        Version revertVersion = new Version(
            doc.id, newNum, targetVersion.content, requester,
            "Reverted to version " + versionNumber);
        doc.versionHistory.add(revertVersion);

        return doc;
    }

    public List<Version> getVersionHistory(User requester, String documentId) {
        Document doc = getDocument(requester, documentId);
        return Collections.unmodifiableList(doc.versionHistory);
    }

    // Expose store for SessionService/ShareService
    public Map<String, Document> getDocumentStore() { return documentStore; }
}
